const DATA_KEY_PROJECTS    = 'portfolio_projects_v2';
const DATA_KEY_POSTS       = 'portfolio_posts_v2';
const DATA_KEY_INITIALIZED = 'portfolio_initialized_v2';
const DATA_KEY_CATEGORIES  = 'portfolio_categories_v3';
const DATA_KEY_HOME        = 'portfolio_home_v3';

function initData() {
  if (!localStorage.getItem(DATA_KEY_INITIALIZED)) {
    localStorage.setItem(DATA_KEY_PROJECTS, JSON.stringify(DEFAULT_PROJECTS));
    localStorage.setItem(DATA_KEY_POSTS, JSON.stringify(DEFAULT_POSTS));
    localStorage.setItem(DATA_KEY_INITIALIZED, '1');
  }
  if (!localStorage.getItem(DATA_KEY_CATEGORIES)) {
    localStorage.setItem(DATA_KEY_CATEGORIES, JSON.stringify(DEFAULT_CATEGORIES));
  }
  if (!localStorage.getItem(DATA_KEY_HOME)) {
    localStorage.setItem(DATA_KEY_HOME, JSON.stringify(DEFAULT_HOME_CONTENT));
  }
}

function getCategories() { initData(); return JSON.parse(localStorage.getItem(DATA_KEY_CATEGORIES) || '[]'); }
function saveCategories(cats) { localStorage.setItem(DATA_KEY_CATEGORIES, JSON.stringify(cats)); }
function getCategoryById(id) { return getCategories().find(c => c.id === id) || { id, name: id, icon: '📁', color: '#888' }; }
function getCategoryNames() { const o={}; getCategories().forEach(c => { o[c.id]=c.name; }); return o; }
let CATEGORY_NAMES = {};
function refreshCategoryNames() { CATEGORY_NAMES = getCategoryNames(); }

function getHomeContent() { initData(); return JSON.parse(localStorage.getItem(DATA_KEY_HOME) || '{}'); }
function saveHomeContent(data) { const cur=getHomeContent(); localStorage.setItem(DATA_KEY_HOME, JSON.stringify({...cur,...data})); }

function getProjects(category) {
  initData();
  let all = JSON.parse(localStorage.getItem(DATA_KEY_PROJECTS) || '[]');
  all.sort((a,b) => { if(a.pinned&&!b.pinned)return -1; if(!a.pinned&&b.pinned)return 1; return (a.order||0)-(b.order||0); });
  if (category) return all.filter(p => p.category === category);
  return all;
}
function getPosts() { initData(); return JSON.parse(localStorage.getItem(DATA_KEY_POSTS) || '[]'); }
function getPostById(id) { return getPosts().find(p => p.id === id) || null; }
function saveProject(project) {
  initData();
  const all = JSON.parse(localStorage.getItem(DATA_KEY_PROJECTS) || '[]');
  const idx = all.findIndex(p => p.id === project.id);
  if (idx >= 0) all[idx] = project; else { project.order = all.length; all.unshift(project); }
  localStorage.setItem(DATA_KEY_PROJECTS, JSON.stringify(all));
}
function deleteProject(id) { initData(); localStorage.setItem(DATA_KEY_PROJECTS, JSON.stringify(JSON.parse(localStorage.getItem(DATA_KEY_PROJECTS)||'[]').filter(p=>p.id!==id))); }
function savePost(post) {
  initData(); const all=getPosts(); const idx=all.findIndex(p=>p.id===post.id);
  if(idx>=0)all[idx]=post; else all.unshift(post);
  localStorage.setItem(DATA_KEY_POSTS, JSON.stringify(all));
}
function deletePost(id) { initData(); localStorage.setItem(DATA_KEY_POSTS, JSON.stringify(getPosts().filter(p=>p.id!==id))); }
function saveProjectsOrder(orderedIds) {
  initData();
  const all = JSON.parse(localStorage.getItem(DATA_KEY_PROJECTS)||'[]');
  orderedIds.forEach((id,idx) => { const p=all.find(x=>x.id===id); if(p)p.order=idx; });
  localStorage.setItem(DATA_KEY_PROJECTS, JSON.stringify(all));
}
function togglePinProject(id) {
  initData();
  const all = JSON.parse(localStorage.getItem(DATA_KEY_PROJECTS)||'[]');
  const p = all.find(x=>x.id===id); if(p)p.pinned=!p.pinned;
  localStorage.setItem(DATA_KEY_PROJECTS, JSON.stringify(all));
}
function genId() { return 'id_'+Date.now()+'_'+Math.random().toString(36).slice(2,7); }

// Collage settings
const DATA_KEY_COLLAGE = 'portfolio_collage_v1';
function getCollageSettings() { const raw=localStorage.getItem(DATA_KEY_COLLAGE); return raw?JSON.parse(raw):{}; }
function saveCollageSettings(s) { localStorage.setItem(DATA_KEY_COLLAGE,JSON.stringify(s)); }
function getCategoryCollage(catId) { const all=getCollageSettings(); return all[catId]||{enabled:false,blur:8,opacity:0.75,cols:3,photos:[]}; }
function setCategoryCollage(catId,cfg) { const all=getCollageSettings(); all[catId]={...getCategoryCollage(catId),...cfg}; saveCollageSettings(all); }
